export type VillagePieceId = keyof typeof VILLAGE_PIECES;

/** An item's art by catalog id; an id the catalog does not know (an old save) shows the "unknown" stone. */
export function itemImage(defId: string): ImageSourcePropType {
  return Object.prototype.hasOwnProperty.call(ITEM_IMAGES, defId) ? ITEM_IMAGES[defId as ItemId] : ICONS.unknown;
}

/** A worker node's art: its tree or its rock. */
export function nodeImage(node: WorkerNodeId): ImageSourcePropType {
  return Object.prototype.hasOwnProperty.call(TREE_IMAGES, node) ? TREE_IMAGES[node as TreeId] : ROCK_IMAGES[node as RockId];
}
